window.AUTH=window.AUTH||{};window.AUTH["17-130"]={"d":"17-130","id":"2017/17-130","n":"Lucia v. Securities and Exchange Commission","briefs":[{"k":"petitioner","label":"Brief of petitioners Raymond J. Lucia, et al.","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-130/36114/20180221144816710_17-130-ts.pdf","side":"pet","n":100},{"k":"respondent","label":"Brief of respondent Securities and Exchange Commission in support of petitioners","date":"2018-02-21","url":"https://www.supremecourt.gov/DocketPDF/17/17-130/36184/20180221202805163_17-130tsUnitedStates.pdf","side":"res","n":80},{"k":"reply","label":"Reply of petitioners Raymond J. Lucia, et al.","date":"2018-04-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-130/43304/20180413120625134_Lucia%20--%20Reply%20Brief.pdf","side":"pet","n":48}],"opinion":null,"tr":true,"items":[{"t":"case","label":"Arthur Andersen LLP v. Carlisle","cite":"556 U.S. 624","y":2009,"id":"2008/08-146","sc":1,"ar":1,"sum":"The Court found that regardless of whether the petitioner is eligible for a stay, a federal court of appeals has jurisdiction over a motion to stay under Section 16(a)(1) of the Federal Arbitration Act.","sumSrc":"Oyez","by":{"0":"51"}},{"t":"case","label":"Auffmordt v. Hedden","cite":"137 U.S. 310","y":1890,"id":"scdb/1890-035","sc":1,"sum":"On a reappraisement by a merchant appraiser and a general appraiser, under § 2930 of the Revised.Statutes, the valuation of goods entered in March, 1886, was raised, and the importer paid thereon additional duties, for which he sued the collector, after protest and appeal. At the trial, the plaintiff put in evidence chapter 3, part 8, articles 447 to 506, and chapter 5, part 8, articles 1399 to 1410, and 1415 to …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18","2":"2"}},{"t":"case","label":"Bandimere v. SEC","cite":"844 F.3d 1168","y":2016,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/844/1168/","by":{"0":"10, 21, 23, 28, 32, 33, 34","1":"20, 22, 34","2":"5"}},{"t":"case","label":"Beck v. Prupis","cite":"529 U.S. 494","y":2000,"id":"1999/98-1480","sc":1,"sum":"The Court held that an injury caused by an overt act that is not an act of racketeering or otherwise wrongful under the Racketeer Influenced and Corrupt Organizations Act does not give rise to a cause of action under RICO. Thus, because Prupis' scheme to remove Beck from SIG was not an act of racketeering itself, Beck had no ground to sue him under RICO.","sumSrc":"Oyez","by":{"0":"35","2":"20"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"ar":2,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"2, 10, 11, 15, 16, 18, 21, 44","1":"passim","2":"1, 2, 9, 12, 17"}},{"t":"case","label":"Burgess v. FDIC","cite":"871 F.3d 297","y":2017,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/871/297/","by":{"0":"28"}},{"t":"case","label":"Butz v. Economou","cite":"438 U.S. 478","y":1978,"id":"1977/76-709","sc":1,"sum":"Federal officials who perform adjudicatory, or other similar prosecutorial functions, cannot, however, be held liable for mere \"good faith\" judgment errors. The Court reasoned that the risk of making unconstitutional determinations is outweighed by the need to preserve independent judgement, through grants of absolute immunity to judges and other similarly situated decision makers.","sumSrc":"Oyez","by":{"0":"30","1":"29, 30"}},{"t":"case","label":"CFTC v. Schor","cite":"478 U.S. 833","y":1986,"id":"1985/85-621","sc":1,"ar":1,"sum":"Section 14 of the Commodity Exchange Act (CEA) provides that any person injured by a commodity broker's violation of the Act or regulations of the Commodity Futures Trading Commission (CFTC) may apply to the CFTC for an order directing the offender to pay reparations to the complainant and may enforce that order in federal district court. The CFTC promulgated a regulation that allows it in a reparations proceeding …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Cook v. Tullis","cite":"85 U.S. 332","y":1874,"id":"scdb/1873-131","sc":1,"sum":"Cook and others, trustees in bankruptcy of the estate of Honians, filed a bill in equity in the coui’t below to set aside the transfer of a certain note for $7000, secured by mortgage, alleged to have been made by the said Homans to-the defendant, Tullís, in violation of the provisions of the Bankrupt Act, and to compel an assignment of the note and mortgage to them.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"52"}},{"t":"case","label":"Dep’t of Transp. v. Ass’n of Am. R.Rs.","cite":"135 S. Ct. 1225","y":2015,"url":"https://www.courtlistener.com/c/S.%20Ct./135/1225/","sc":1,"by":{"0":"31, 51","2":"9"}},{"t":"case","label":"Edmond v. United States","cite":"520 U.S. 651","y":1997,"id":"1996/96-262","sc":1,"ar":3,"sum":"The Court held that the judicial appointments were valid. The Court unanimously found that Congress has authorized the Secretary to appoint civilian members of the Coast Guard Court of Criminal Appeals.","sumSrc":"Oyez","by":{"0":"2, 12, 13, 17, 19, 29, 30, 31, 38, 50, 57","1":"11, 16, 35, 36","2":"1, 2, 3, 7, 8, 9, 12, 13, 14, 17, 20, 22"}},{"t":"case","label":"FEC v. NRA Political Victory Fund","cite":"513 U.S. 88","y":1994,"id":"1994/93-1151","sc":1,"sum":"Petitioner Federal Election Commission (FEC) brought this civil action against respondents seeking to enforce a provision of the Federal Election Campaign Act of 1971 (FECA). The District Court ruled against respondents. The Court of Appeals reversed and entered its judgment on October 22, 1993. Without first seeking or obtaining the Solicitor General's authorization, the FEC filed in its own name a petition for a …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 52"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"0":"4, 30, 36, 38, 41, 51","1":"passim","2":"2, 5, 12, 16, 17"}},{"t":"case","label":"Free Enter. Fund v. PCAOB","cite":"537 F.3d 667","y":2008,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/537/667/","by":{"0":"30","2":"13"}},{"t":"case","label":"Freytag v. Comm’r","cite":"501 U.S. 868","y":1991,"id":"1990/90-762","sc":1,"ar":16,"sum":"On the question of whether 7443A permitted the assignment of complex cases to special trial judges, the Supreme Court unanimously ruled that the statute unambiguously did allow such appointments. Justice Harry Blackmun, in the majority opinion, wrote, \"The plain language of 7443A(b)(4) surely authorizes the Chief Judge's assignment of petitioners' cases to a special trial judge.","sumSrc":"Oyez","by":{"0":"2, 11, 12, 14, 17, 19, 20, 21, 23, 26, 27, 33, 41, 42, 43, 44, 45, 52, 57","1":"passim","2":"1, 3, 6, 8, 9, 12, 14, 16, 23, 7"}},{"t":"case","label":"Go-Bart Importing Co. v. United States","cite":"282 U.S. 344","y":1931,"id":"scdb/1930-123","sc":1,"sum":"(1) In the proceedings before him, the Commissionek acted merely as an officer of the District Court in a matter of which it had authority to take control at any time. P. 353. (2) Notwithstanding the order to show cause was addressed to the United States alone, the proceeding was in substance and effect against the United States Attorney and the prohibition agent in charge, the latter being required by the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"18, 20, 28, 29","2":"2"}},{"t":"case","label":"Greenlaw v. United States","cite":"554 U.S. 237","y":2008,"id":"2007/07-330","sc":1,"sum":"The Court stated that the Eighth Circuit could not order the district court to increase Greenlaw's sentence without a request from the government to do so. The Court pointed to several of its precedents for the rule that a remedy in favor the appellee, in this case the government, can only be justified if the appellee brings a cross-appeal.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Humphrey’s Executor v. United States","cite":"295 U.S. 602","y":1935,"id":"1900-1940/295us602","sc":1,"sum":"The unanimous Court found that the FTC Act was constitutional and that Humphrey's dismissal on policy grounds was unjustified. The Court reasoned that the Constitution had never given \"illimitable power of removal\" to the president. Justice Sutherland dismissed the government's main line of defense in this case which relied heavily on the Court's decision in Myers v. United States (1926).","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"ICC v. Brimson","cite":"154 U.S. 447","y":1894,"id":"scdb/1893-293","sc":1,"sum":"The twelfth section of the Interstate Commerce Act authorizing the Circuit Courts of the United States to use their process in aid of inquiries befbre the Commission established by that'act, is not in conflict with the Constitution of the United States, as imposing on judicial tribunals duties not judicial in their nature.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"23","2":"6"}},{"t":"case","label":"Intercollegiate Broad. Sys., Inc. v. Copyright Royalty Bd.","cite":"796 F.3d 111","y":2015,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/796/111/","by":{"0":"55, 56"}},{"t":"case","label":"Landry v. FDIC","cite":"204 F.3d 1125","y":2000,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/204/1125/","by":{"0":"9, 26, 28, 34","1":"9, 33, 34","2":"18"}},{"t":"case","label":"McAllister v. United States","cite":"141 U.S. 174","y":1891,"id":"scdb/1890-298","sc":1,"sum":"A person appointed by the President, by and with the advice and consent of the Senate, under the provisions of'the act of May 17, 1884, 23 Stat. 24, c. 53, § 3, to be the judge of the District Court of the District of Alaska, is not a judge of a court óf the United States within the meaning of the exception in section 1768 of the Revised Statutes, relating to the tenure of office of civil officers, and was, prior to …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Myers v. United States","cite":"272 U.S. 52","y":1926,"id":"1900-1940/272us52","sc":1,"sum":"After tracing legislative debate of the First Congress in 1789 which dealt with the interpretation of the President's appointment power, Chief Justice Taft concluded that the power to remove appointed officers is vested in the President alone. According to Taft, to deny the President that power would not allow him to \"discharge his own constitutional duty of seeing that the laws be faithfully executed.\".","sumSrc":"Oyez","by":{"0":"18","1":"40, 41, 50, 51","2":"13"}},{"t":"case","label":"Newman v. Schiff","cite":"778 F.2d 460","y":1985,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/778/460/","by":{"0":"52"}},{"t":"case","label":"Nguyen v. United States","cite":"539 U.S. 69","y":2003,"id":"2002/01-10873","sc":1,"sum":"The Court held that the Court of Appeals panel did not have the authority to decide Nguyen and Phan's appeals. The Court reasoned that the territorial judge was precluded from designation to the panel and thus the defendants' appeals required reconsideration by a properly constituted panel.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"NLRB v. Noel Canning","cite":"134 S. Ct. 2550","y":2014,"url":"https://www.courtlistener.com/c/S.%20Ct./134/2550/","sc":1,"by":{"0":"36"}},{"t":"case","label":"Palmore v. United States","cite":"411 U.S. 389","y":1973,"id":"1972/72-11","sc":1,"sum":"1 1. The District of Columbia Code is not a state statute for purposes of § 1257 (2), and the lower court's upholding of the federal statute is therefore not reviewable by appeal but by certiorari.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Ramspeck v. Fed. Trial Exam’rs Conference","cite":"345 U.S. 128","y":1953,"id":"scdb/1952-062","sc":1,"sum":"Certain -provisions of regulations promulgated by the Civil Service Commission under § 11 of the Administrative Procedure Act and governing the classification, promotion, compensation fnd tenure of trial examiners and the assignment of cases to them are here sustained as conforming to the statute and carrying out the purpose and intent of Congress.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"3, 36, 37","1":"27, 49, 53","2":"19"}},{"t":"case","label":"Rice v. Ames","cite":"180 U.S. 371","y":1901,"id":"scdb/1900-121","sc":1,"sum":"An appeal lies directly to this court from a judgment of the District Court in a habeas corpus case, where the constitutionality of a law of thp United States, or the validity or construction of a treaty is drawn in question.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18"}},{"t":"case","label":"Ryder v. United States","cite":"515 U.S. 177","y":1995,"id":"1994/94-431","sc":1,"ar":1,"sum":"The Court held that the judges' actions were not valid de facto. The Court reasoned that a defendant who made a timely challenge to the constitutional validity of the appointment of an officer who adjudicates his case was entitled to a decision on the merits of the question and whatever relief may be appropriate if a violation had occurred.","sumSrc":"Oyez","by":{"0":"12, 13, 20, 30, 43, 44, 45, 47, 54, 55, 57","2":"21, 22"}},{"t":"case","label":"Samuels, Kramer & Co. v. Comm’r","cite":"930 F.2d 975","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/930/975/","by":{"0":"28"}},{"t":"case","label":"SEC v. Chenery Corp.","cite":"318 U.S. 80","y":1943,"id":"scdb/1942-113","sc":1,"sum":"By an order of the Securities and Exchange Commission under the Public Utility Holding Company Act of 1935, approval was given, over objections, to a plan for the reorganization of a registered holding company, whereby preferred stock which had been acquired by officers and directors of the company while plans for its reorganization were before the Commission, would not be converted into stock of the reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"53"}},{"t":"case","label":"Tumey v. Ohio","cite":"273 U.S. 510","y":1927,"id":"scdb/1926-164","sc":1,"sum":"violative of the Fourteenth Amendment. Pp. 520, 531. 115 Oh. St. 701, reversed. ERROR to a judgment of the Supreme Court of Ohio, which declined to review a judgment of the State Court of Appeals, 22 Oh. L. Rep. 634, reversing a judgment of the Court of Common Pleas of Hamilton County, 25 Oh. Nisi Prius (N. S.) 580, which reversed a judgment of the Iayor of the Village of North College Hill convicting and fining …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"United States v. Allred","cite":"155 U.S. 591","y":1895,"id":"scdb/1894-064","sc":1,"sum":"A commissioner of a Circuit Court is an officer of the court, authorized by law, and is entitled to his fees in the following cases when certified by the court as correct:","sumSrc":"Headnote (U.S. Reports)","by":{"0":"18, 20, 28, 29"}},{"t":"case","label":"United States v. Germaine","cite":"99 U.S. 508","y":1879,"id":"scdb/1878-198","sc":1,"sum":"1. Civil surgeons appointed by the Commissioner of Pensions under sect. 4777 of the Revised Statutes are not officers of the United States.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"12, 17, 35","1":"16, 17, 18, 25","2":"10, 19"}},{"t":"case","label":"United States v. L.A. Tucker Truck Lines, Inc.","cite":"344 U.S. 33","y":1952,"id":"scdb/1952-007","sc":1,"ar":1,"sum":"The district court should not entertain this objection when first made at that stage of the proceedings.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 43, 44, 46, 49, 56"}},{"t":"case","label":"United States v. Moore","cite":"95 U.S. 760","y":1878,"id":"scdb/1877-140","sc":1,"sum":"This was an action in the Court of Claims by Andrew M. Moore against the United States, to recover certain pay which he alleged was due him as an officer in the navy. -","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17"}},{"t":"case","label":"United States v. Perkins","cite":"116 U.S. 483","y":1886,"id":"scdb/1885-120","sc":1,"sum":"When Congress by law, vests the appointment of inferior officers in the heads of departments, it may limit and restrict the power of removal as it deems best for the public interests.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"17","1":"42"}},{"t":"case","label":"Vasquez v. Hillery","cite":"474 U.S. 254","y":1986,"id":"1985/84-836","sc":1,"sum":"The Court held that Hillery was allowed to pursue his claim in federal court because the district court was within its power to request additional evidence that did not fundamentally alter the legal claim that the state courts already considered.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Waller v. Georgia","cite":"467 U.S. 39","y":1984,"id":"1983/83-321","sc":1,"sum":"The Court held that the Sixth Amendment right to a public trial applied to suppression hearings.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Ward v. Vill. of Monroeville","cite":"409 U.S. 57","y":1972,"id":"1972/71-496","sc":1,"sum":"Petitioner was denied a trial before a disinterested and impartial judicial officer as guaranteed by the Due Process Clause of the Fourteenth Amendment where he was compelled to stand trial for traffic offenses before the mayor, who was responsible for village finances and whose court through fines, forfeitures, costs, and fees provided a substantial portion of village funds. Tumey v. Ohio, 273 U. S. 510. A …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Weaver v. Massachusetts","cite":"137 S. Ct. 1899","y":2017,"id":"2016/16-240","sc":1,"sum":"The Court determined that, in the context of the violation of a right to a public trial during jury selection, when the structural error was first raised via an ineffective assistance of counsel claim, the defendant must demonstrate that he suffered prejudice in order to secure a new trial.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Weiss v. United States","cite":"510 U.S. 163","y":1994,"id":"1993/92-1482","sc":1,"ar":2,"sum":"Mter courts-martial sentenced petitioners Weiss and Hernandez, United States Marines, on their pleas of guilty to offenses under the Uniform Code of Military Justice (UCMJ), their convictions were affirmed by the Navy-Marine Corps Court of Military Review in separate appeals. In affirming Weiss' conviction, the Court of Military Appeals rejected his contentions, first, that military trial and appellate judges have …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 28, 29","2":"3, 8"}},{"t":"case","label":"Williams v. Pennsylvania","cite":"136 S. Ct. 1899","y":2016,"id":"2015/15-5040","sc":1,"sum":"The Court determined that the Eighth and Fourteenth Amendments are violated when a judge who was previously involved in the case as a prosecutor declines to recuse himself, regardless of whether that judge’s decision as part of a multi-member tribunal was dispositive.","sumSrc":"Oyez","by":{"0":"12, 45, 46, 56"}},{"t":"case","label":"Withrow v. Larkin","cite":"421 U.S. 35","y":1975,"id":"1974/73-1573","sc":1,"sum":"Wisconsin statutes prohibit various acts of professional misconduct by physicians and empower a State Examining Board to warn and reprimand physicians, to temporarily suspend licenses, and to institute criminal action or action to revoke a license. When the Board notified appellee licensed physician that a closed investigative hearing, which appellee and his attorney could attend, would be held to determine whether …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"47"}},{"t":"const","label":"Article II, Section 2, Clause 2","clauses":[["treaty","Treaty Clause"],["appointments","Appointments Clause"]],"text":"He shall have Power, by and with the Advice and Consent of the Senate, to make Treaties, provided two thirds of the Senators present concur; and he shall nominate, and by and with the Advice and Consent of the Senate, shall appoint Ambassadors, other public Ministers and Consuls, Judges of the supreme Court, and all other Officers of the United States, whose Appointments are not herein otherwise provided for, and which shall be established by Law: but the Congress may by Law vest the Appointment of such inferior Officers, as they think proper, in the President alone, in the Courts of Law, or in the Heads of Departments.","by":{"0":"2, 11, 14, 15, 16, 31, 36, 51, 53","2":"11, 12, 20"}},{"t":"const","label":"Article II, Section 3","clauses":[["take-care","Take Care Clause"]],"text":"He shall from time to time give to the Congress Information of the State of the Union, and recommend to their Consideration such Measures as he shall judge necessary and expedient; he may, on extraordinary Occasions, convene both Houses, or either of them, and in Case of Disagreement between them, with Respect to the Time of Adjournment, he may adjourn them to such Time as he shall think proper; he shall receive Ambassadors and other public Ministers; he shall take Care that the Laws be faithfully executed, and shall Commission all the Officers of the United States.","by":{"0":"51"}},{"t":"const","label":"Article III, Section 1","clauses":[["judicial-vesting","Judicial Vesting Clause"]],"text":"The judicial Power of the United States, shall be vested in one supreme Court, and in such inferior Courts as the Congress may from time to time ordain and establish. The Judges, both of the supreme and inferior Courts, shall hold their Offices during good Behaviour, and shall, at stated Times, receive for their Services, a Compensation, which shall not be diminished during their Continuance in Office.","by":{"0":"39"}},{"t":"const","label":"Article VI, Clause 3","clauses":[["religious-test","No Religious Test Clause"]],"text":"The Senators and Representatives before mentioned, and the Members of the several State Legislatures, and all executive and judicial Officers, both of the United States and of the several States, shall be bound by Oath or Affirmation, to support this Constitution; but no religious Test shall ever be required as a Qualification to any Office or public Trust under the United States.","by":{"0":"51"}},{"t":"usc","label":"5 U.S.C. § 556","url":"https://www.law.cornell.edu/uscode/text/5/556","subs":["(b)"],"stext":{"head":"§556. Hearings; presiding employees; powers and duties; burden of proof; evidence; record as basis of decision","paras":[[0,"(a) This section applies, according to the provisions thereof, to hearings required by section 553 or 554 of this title to be conducted in accordance with this section."],[0,"(b) There shall preside at the taking of evidence—"],[1,"(1) the agency;"],[1,"(2) one or more members of the body which comprises the agency; or"],[1,"(3) one or more administrative law judges appointed under section 3105 of this title."],[0,"This subchapter does not supersede the conduct of specified classes of proceedings, in whole or in part, by or before boards or other employees specially provided for by or designated under statute. The functions of presiding employees and of employees participating in decisions in accordance with section 557 of this title shall be conducted in an impartial manner. A presiding or participating employee may at any time disqualify himself. On the filing in good faith of a timely and sufficient affidavit of personal bias or other disqualification of a presiding or participating employee, the agency shall determine the matter as a part of the record and decision in the case."],[0,"(c) Subject to published rules of the agency and within its powers, employees presiding at hearings may—"],[1,"(1) administer oaths and affirmations;"],[1,"(2) issue subpenas authorized by law;"],[1,"(3) rule on offers of proof and receive relevant evidence;"],[1,"(4) take depositions or have depositions taken when the ends of justice would be served;"],[1,"(5) regulate the course of the hearing;"],[1,"(6) hold conferences for the settlement or simplification of the issues by consent of the parties or by the use of alternative means of dispute resolution as provided in subchapter IV of this chapter;"],[1,"(7) inform the parties as to the availability of one or more alternative means of dispute resolution, and encourage use of such methods;"],[1,"(8) require the attendance at any conference held pursuant to paragraph (6) of at least one representative of each party who has authority to negotiate concerning resolution of issues in controversy;"],[1,"(9) dispose of procedural requests or similar matters;"],[1,"(10) make or recommend decisions in accordance with section 557 of this title; and"],[1,"(11) take other action authorized by agency rule consistent with this subchapter."],[0,"(d) Except as otherwise provided by statute, the proponent of a rule or order has the burden of proof. Any oral or documentary evidence may be received, but the agency as a matter of policy shall provide for the exclusion of irrelevant, immaterial, or unduly repetitious evidence. A sanction may not be imposed or rule or order issued except on consideration of the whole record or those parts thereof cited by a party and supported by and in accordance with the reliable, probative, and substantial evidence. The agency may, to the extent consistent with the interests of justice and the policy of the underlying statutes administered by the agency, consider a violation of section 557(d) of this title sufficient grounds for a decision adverse to a party who has knowingly committed such violation or knowingly caused such violation to occur. A party is entitled to present his case or defense by oral or documentary evidence, to submit rebuttal evidence, and to conduct such cross-examination as may be required for a full and true disclosure of the facts. In rule making or determining claims for money or benefits or applications for initial licenses an agency may, when a party will not be prejudiced thereby, adopt procedures for the submission of all or part of the evidence in written form."],[0,"(e) The transcript of testimony and exhibits, together with all papers and requests filed in the proceeding, constitutes the exclusive record for decision in accordance with section 557 of this title and, on payment of lawfully prescribed costs, shall be made available to the parties. When an agency decision rests on official notice of a material fact not appearing in the evidence in the record, a party is entitled, on timely request, to an opportunity to show the contrary."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/556?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§556. Hearings; presiding employees; powers and duties; burden of proof; evidence; record as basis of decision","tname":"Government Organization and Employees","by":{"0":"3, 11, 21, 38, 41, 48, 54, 56","1":"5, 5","2":"20"}},{"t":"usc","label":"5 U.S.C. § 557","url":"https://www.law.cornell.edu/uscode/text/5/557","subs":["(b)"],"stext":{"head":"§557. Initial decisions; conclusiveness; review by agency; submissions by parties; contents of decisions; record","paras":[[0,"(a) This section applies, according to the provisions thereof, when a hearing is required to be conducted in accordance with section 556 of this title."],[0,"(b) When the agency did not preside at the reception of the evidence, the presiding employee or, in cases not subject to section 554(d) of this title, an employee qualified to preside at hearings pursuant to section 556 of this title, shall initially decide the case unless the agency requires, either in specific cases or by general rule, the entire record to be certified to it for decision. When the presiding employee makes an initial decision, that decision then becomes the decision of the agency without further proceedings unless there is an appeal to, or review on motion of, the agency within time provided by rule. On appeal from or review of the initial decision, the agency has all the powers which it would have in making the initial decision except as it may limit the issues on notice or by rule. When the agency makes the decision without having presided at the reception of the evidence, the presiding employee or an employee qualified to preside at hearings pursuant to section 556 of this title shall first recommend a decision, except that in rule making or determining applications for initial licenses—"],[1,"(1) instead thereof the agency may issue a tentative decision or one of its responsible employees may recommend a decision; or"],[1,"(2) this procedure may be omitted in a case in which the agency finds on the record that due and timely execution of its functions imperatively and unavoidably so requires."],[0,"(c) Before a recommended, initial, or tentative decision, or a decision on agency review of the decision of subordinate employees, the parties are entitled to a reasonable opportunity to submit for the consideration of the employees participating in the decisions—"],[1,"(1) proposed findings and conclusions; or"],[1,"(2) exceptions to the decisions or recommended decisions of subordinate employees or to tentative agency decisions; and"],[1,"(3) supporting reasons for the exceptions or proposed findings or conclusions."],[0,"The record shall show the ruling on each finding, conclusion, or exception presented. All decisions, including initial, recommended, and tentative decisions, are a part of the record and shall include a statement of—"],[1,"(A) findings and conclusions, and the reasons or basis therefor, on all the material issues of fact, law, or discretion presented on the record; and"],[1,"(B) the appropriate rule, order, sanction, relief, or denial thereof."],[0,"(d)(1) In any agency proceeding which is subject to subsection (a) of this section, except to the extent required for the disposition of ex parte matters as authorized by law—"],[1,"(A) no interested person outside the agency shall make or knowingly cause to be made to any member of the body comprising the agency, administrative law judge, or other employee who is or may reasonably be expected to be involved in the decisional process of the proceeding, an ex parte communication relevant to the merits of the proceeding;"],[1,"(B) no member of the body comprising the agency, administrative law judge, or other employee who is or may reasonably be expected to be involved in the decisional process of the proceeding, shall make or knowingly cause to be made to any interested person outside the agency an ex parte communication relevant to the merits of the proceeding;"],[1,"(C) a member of the body comprising the agency, administrative law judge, or other employee who is or may reasonably be expected to be involved in the decisional process of such proceeding who receives, or who makes or knowingly causes to be made, a communication prohibited by this subsection shall place on the public record of the proceeding:"],[2,"(i) all such written communications;"],[2,"(ii) memoranda stating the substance of all such oral communications; and"],[2,"(iii) all written responses, and memoranda stating the substance of all oral responses, to the materials described in clauses (i) and (ii) of this subparagraph;"],[1,"(D) upon receipt of a communication knowingly made or knowingly caused to be made by a party in violation of this subsection, the agency, administrative law judge, or other employee presiding at the hearing may, to the extent consistent with the interests of justice and the policy of the underlying statutes, require the party to show cause why his claim or interest in the proceeding should not be dismissed, denied, disregarded, or otherwise adversely affected on account of such violation; and"],[1,"(E) the prohibitions of this subsection shall apply beginning at such time as the agency may designate, but in no case shall they begin to apply later than the time at which a proceeding is noticed for hearing unless the person responsible for the communication has knowledge that it will be noticed, in which case the prohibitions shall apply beginning at the time of his acquisition of such knowledge."],[0,"(2) This subsection does not constitute authority to withhold information from Congress."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/557?type=usc&year=mostrecent&link-type=html"},"head":"§557. Initial decisions; conclusiveness; review by agency; submissions by parties; contents of decisions; record","tname":"Government Organization and Employees","by":{"0":"3, 11, 21, 23, 32, 38","1":"5, 5","2":"5, 14"}},{"t":"usc","label":"5 U.S.C. § 706","url":"https://www.law.cornell.edu/uscode/text/5/706","stext":{"head":"§706. Scope of review","paras":[[0,"To the extent necessary to decision and when presented, the reviewing court shall decide all relevant questions of law, interpret constitutional and statutory provisions, and determine the meaning or applicability of the terms of an agency action. The reviewing court shall—"],[1,"(1) compel agency action unlawfully withheld or unreasonably delayed; and"],[1,"(2) hold unlawful and set aside agency action, findings, and conclusions found to be—"],[2,"(A) arbitrary, capricious, an abuse of discretion, or otherwise not in accordance with law;"],[2,"(B) contrary to constitutional right, power, privilege, or immunity;"],[2,"(C) in excess of statutory jurisdiction, authority, or limitations, or short of statutory right;"],[2,"(D) without observance of procedure required by law;"],[2,"(E) unsupported by substantial evidence in a case subject to sections 556 and 557 of this title or otherwise reviewed on the record of an agency hearing provided by statute; or"],[2,"(F) unwarranted by the facts to the extent that the facts are subject to trial de novo by the reviewing court."],[0,"In making the foregoing determinations, the court shall review the whole record or those parts of it cited by a party, and due account shall be taken of the rule of prejudicial error."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/706?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§706. Scope of review","tname":"Government Organization and Employees","by":{"0":"42","2":"22"}},{"t":"usc","label":"5 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/5/1202","subs":["(d)"],"stext":{"head":"§1202. Term of office; filling vacancies; removal","paras":[[0,"(a) The term of office of each member of the Merit Systems Protection Board is 7 years."],[0,"(b) A member appointed to fill a vacancy occurring before the end of a term of office of the member's predecessor serves for the remainder of that term. Any appointment to fill a vacancy is subject to the requirements of section 1201. Any new member serving only a portion of a seven-year term in office may continue to serve until a successor is appointed and has qualified, except that such member may not continue to serve for more than one year after the date on which the term of the member would otherwise expire, unless reappointed."],[0,"(c) Any member appointed for a 7-year term may not be reappointed to any following term but may continue to serve beyond the expiration of the term until a successor is appointed and has qualified, except that such member may not continue to serve for more than one year after the date on which the term of the member would otherwise expire under this section."],[0,"(d) Any member may be removed by the President only for inefficiency, neglect of duty, or malfeasance in office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/1202?type=usc&year=mostrecent&link-type=html"},"head":"§1202. Term of office; filling vacancies; removal","tname":"Government Organization and Employees","by":{"0":"37","1":"5, 45"}},{"t":"usc","label":"5 U.S.C. § 2104","url":"https://www.law.cornell.edu/uscode/text/5/2104","stext":{"head":"§2104. Officer","paras":[[0,"(a) For the purpose of this title, \"officer\", except as otherwise provided by this section or when specifically modified, means a justice or judge of the United States and an individual who is—"],[1,"(1) required by law to be appointed in the civil service by one of the following acting in an official capacity—"],[2,"(A) the President;"],[2,"(B) a court of the United States;"],[2,"(C) the head of an Executive agency; or"],[2,"(D) the Secretary of a military department;"],[1,"(2) engaged in the performance of a Federal function under authority of law or an Executive act; and"],[1,"(3) subject to the supervision of an authority named by paragraph (1) of this section, or the Judicial Conference of the United States, while engaged in the performance of the duties of his office."],[0,"(b) Except as otherwise provided by law, an officer of the United States Postal Service or of the Postal Regulatory Commission is deemed not an officer for purposes of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/2104?type=usc&year=mostrecent&link-type=html"},"head":"§2104. Officer","tname":"Government Organization and Employees","by":{"0":"36","2":"20"}},{"t":"usc","label":"5 U.S.C. § 3105","url":"https://www.law.cornell.edu/uscode/text/5/3105","stext":{"head":"§3105. Appointment of administrative law judges","paras":[[0,"Each agency shall appoint as many administrative law judges as are necessary for proceedings required to be conducted in accordance with sections 556 and 557 of this title. Administrative law judges shall be assigned to cases in rotation so far as practicable, and may not perform duties inconsistent with their duties and responsibilities as administrative law judges."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/3105?type=usc&year=mostrecent&link-type=html"},"head":"§3105. Appointment of administrative law judges","tname":"Government Organization and Employees","by":{"0":"3, 21, 38","1":"5"}},{"t":"usc","label":"5 U.S.C. § 5372","url":"https://www.law.cornell.edu/uscode/text/5/5372","subs":["(b)"],"stext":{"head":"§5372. Administrative law judges","paras":[[0,"(a) For the purposes of this section, the term \"administrative law judge\" means an administrative law judge appointed under section 3105."],[0,"(b)(1)(A) There shall be 3 levels of basic pay for administrative law judges (designated as AL–1, 2, and 3, respectively), and each such judge shall be paid at 1 of those levels, in accordance with the provisions of this section."],[0,"(B) Within level AL–3, there shall be 6 rates of basic pay, designated as AL–3, rates A through F, respectively. Level AL–2 and level AL–1 shall each have 1 rate of basic pay."],[0,"(C) The rate of basic pay for AL–3, rate A, may not be less than 65 percent of the rate of basic pay for level IV of the Executive Schedule, and the rate of basic pay for AL–1 may not exceed the rate for level IV of the Executive Schedule."],[0,"(2) The Office of Personnel Management shall determine, in accordance with procedures which the Office shall by regulation prescribe, the level in which each administrative-law-judge position shall be placed and the qualifications to be required for appointment to each level."],[0,"(3)(A) Upon appointment to a position in AL–3, an administrative law judge shall be paid at rate A of AL–3, and shall be advanced successively to rates B, C, and D of that level at the beginning of the next pay period following completion of 52 weeks of service in the next lower rate, and to rates E and F of that level at the beginning of the next pay period following completion of 104 weeks of service in the next lower rate."],[0,"(B) The Office of Personnel Management may provide for appointment of an administrative law judge in AL–3 at an advanced rate under such circumstances as the Office may determine appropriate."],[0,"(4) Subject to paragraph (1), effective at the beginning of the first applicable pay period commencing on or after the first day of the month in which an adjustment takes effect under section 5303 in the rates of basic pay under the General Schedule, each rate of basic pay for administrative law judges shall be adjusted by an amount determined by the President to be appropriate."],[0,"(c) The Office of Personnel Management shall prescribe regulations necessary to administer this section."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/5372?type=usc&year=mostrecent&link-type=html"},"head":"§5372. Administrative law judges","tname":"Government Organization and Employees","by":{"0":"3, 21","1":"20"}},{"t":"usc","label":"5 U.S.C. § 7521","url":"https://www.law.cornell.edu/uscode/text/5/7521","subs":["(a)","(b)","(b)(1)"],"stext":{"head":"§7521. Actions against administrative law judges","paras":[[0,"(a) An action may be taken against an administrative law judge appointed under section 3105 of this title by the agency in which the administrative law judge is employed only for good cause established and determined by the Merit Systems Protection Board on the record after opportunity for hearing before the Board."],[0,"(b) The actions covered by this section are—"],[1,"(1) a removal;"],[1,"(2) a suspension;"],[1,"(3) a reduction in grade;"],[1,"(4) a reduction in pay; and"],[1,"(5) a furlough of 30 days or less;"],[0,"but do not include—"],[1,"(A) a suspension or removal under section 7532 of this title;"],[1,"(B) a reduction-in-force action under section 3502 of this title; or"],[1,"(C) any action initiated under section 1215 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/7521?type=usc&year=mostrecent&link-type=html"},"head":"§7521. Actions against administrative law judges","tname":"Government Organization and Employees","by":{"0":"3, 21, 38","1":"54, 54, 54, 54"}},{"t":"usc","label":"10 U.S.C. § 866","url":"https://www.law.cornell.edu/uscode/text/10/866","by":{"0":"19"}},{"t":"usc","label":"10 U.S.C. § 867","url":"https://www.law.cornell.edu/uscode/text/10/867","stext":{"head":"§867. Art. 67. Review by the Court of Appeals for the Armed Forces","paras":[[0,"(a) The Court of Appeals for the Armed Forces shall review the record in—"],[1,"(1) all cases in which the sentence, as affirmed by a Court of Criminal Appeals, extends to death;"],[1,"(2) all cases reviewed by a Court of Criminal Appeals which the Judge Advocate General, after appropriate notification to the other Judge Advocates General and the Staff Judge Advocate to the Commandant of the Marine Corps, orders sent to the Court of Appeals for the Armed Forces for review; and"],[1,"(3) all cases reviewed by a Court of Criminal Appeals in which, upon petition of the accused and on good cause shown, the Court of Appeals for the Armed Forces has granted a review."],[0,"(b) The accused may petition the Court of Appeals for the Armed Forces for review of a decision of a Court of Criminal Appeals within 60 days from the earlier of—"],[1,"(1) the date on which the accused is notified of the decision of the Court of Criminal Appeals; or"],[1,"(2) the date on which a copy of the decision of the Court of Criminal Appeals, after being served on appellate counsel of record for the accused (if any), is deposited in the United States mails for delivery by first-class certified mail to the accused at an address provided by the accused or, if no such address has been provided by the accused, at the latest address listed for the accused in his official service record."],[0,"The Court of Appeals for the Armed Forces shall act upon such a petition promptly in accordance with the rules of the court."],[0,"(c)(1) In any case reviewed by it, the Court of Appeals for the Armed Forces may act only with respect to—"],[1,"(A) the findings and sentence set forth in the entry of judgment, as affirmed or set aside as incorrect in law by the Court of Criminal Appeals;"],[1,"(B) a decision, judgment, or order by a military judge, as affirmed or set aside as incorrect in law by the Court of Criminal Appeals; or"],[1,"(C) the findings set forth in the entry of judgment, as affirmed, dismissed, set aside, or modfied by the Court of Criminal Appeals as incorrect in fact under section 866(d)(1)(B) of this title (article 66(d)(1)(B))."],[0,"(2) In a case which the Judge Advocate General orders sent to the Court of Appeals for the Armed Forces, that action need be taken only with respect to the issues raised by him."],[0,"(3) In a case reviewed upon petition of the accused, that action need be taken only with respect to issues specified in the grant of review."],[0,"(4) The Court of Appeals for the Armed Forces shall take action only with respect to matters of law."],[0,"(d) If the Court of Appeals for the Armed Forces sets aside the findings and sentence, it may, except where the setting aside is based on lack of sufficient evidence in the record to support the findings, order a rehearing. If it sets aside the findings and sentence and does not order a rehearing, it shall order that the charges be dismissed."],[0,"(e) After it has acted on a case, the Court of Appeals for the Armed Forces may direct the Judge Advocate General to return the record to the Court of Criminal Appeals for further review in accordance with the decision of the court. Otherwise, unless there is to be further action by the President or the Secretary concerned, the Judge Advocate General shall instruct the convening authority to take action in accordance with that decision. If the court has ordered a rehearing, but the convening authority finds a rehearing impracticable, he may dismiss the charges. Notwithstanding the preceding sentence, if a case was referred to trial by a special trial counsel, a special trial counsel shall determine if a rehearing is impracticable and shall dismiss the charges if the special trial counsel so determines."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/10/867?type=usc&year=mostrecent&link-type=html"},"head":"§867. Art. 67. Review by the Court of Appeals for the Armed Forces","tname":"Armed Forces","by":{"0":"29","2":"9"}},{"t":"usc","label":"15 U.S.C. § 77u","url":"https://www.law.cornell.edu/uscode/text/15/77u","stext":{"head":"§77u. Hearings by Commission","paras":[[0,"All hearings shall be public and may be held before the Commission or an officer or officers of the Commission designated by it, and appropriate records thereof shall be kept."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/77u?type=usc&year=mostrecent&link-type=html"},"head":"§77u. Hearings by Commission","tname":"Commerce and Trade","by":{"0":"3, 35","2":"20"}},{"t":"usc","label":"15 U.S.C. § 78d","url":"https://www.law.cornell.edu/uscode/text/15/78d","stext":{"head":"§78d. Securities and Exchange Commission","paras":[[0,"(a) Establishment; composition; limitations on commissioners; terms of office"],[0,"There is hereby established a Securities and Exchange Commission (hereinafter referred to as the \"Commission\") to be composed of five commissioners to be appointed by the President by and with the advice and consent of the Senate. Not more than three of such commissioners shall be members of the same political party, and in making appointments members of different political parties shall be appointed alternately as nearly as may be practicable. No commissioner shall engage in any other business, vocation, or employment than that of serving as commissioner, nor shall any commissioner participate, directly or indirectly, in any stock-market operations or transactions of a character subject to regulation by the Commission pursuant to this chapter. Each commissioner shall hold office for a term of five years and until his successor is appointed and has qualified, except that he shall not so continue to serve beyond the expiration of the next session of Congress subsequent to the expiration of said fixed term of office, and except (1) any commissioner appointed to fill a vacancy occurring prior to the expiration of the term for which his predecessor was appointed shall be appointed for the remainder of such term, and (2) the terms of office of the commissioners first taking office after June 6, 1934, shall expire as designated by the President at the time of nomination, one at the end of one year, one at the end of two years, one at the end of three years, one at the end of four years, and one at the end of five years, after June 6, 1934."],[0,"(b) Appointment and compensation of staff and leasing authority"],[0,"(1) Appointment and compensation"],[1,"The Commission shall appoint and compensate officers, attorneys, economists, examiners, and other employees in accordance with section 4802 of title 5."],[0,"(2) Reporting of information"],[1,"In establishing and adjusting schedules of compensation and benefits for officers, attorneys, economists, examiners, and other employees of the Commission under applicable provisions of law, the Commission shall inform the heads of the agencies referred to under section 1833b of title 12 and Congress of such compensation and benefits and shall seek to maintain comparability with such agencies regarding compensation and benefits."],[0,"(3) Leasing authority"],[1,"Nothwithstanding 1 any other provision of law, the Commission is authorized to enter directly into leases for real property for office, meeting, storage, and such other space as is necessary to carry out its functions, and shall be exempt from any General Services Administration space management regulations or directives."],[0,"(c) Acceptance of travel support for Commission activities from non-Federal sources; regulations"],[0,"Notwithstanding any other provision of law, in accordance with regulations which the Commission shall prescribe to prevent conflicts of interest, the Commission may accept payment and reimbursement, in cash or in kind, from non-Federal agencies, organizations, and individuals for travel, subsistence, and other necessary expenses incurred by Commission members and employees in attending meetings and conferences concerning the functions or activities of the Commission. Any payment or reimbursement accepted shall be credited to the appropriated funds of the Commission. The amount of travel, subsistence, and other necessary expenses for members and employees paid or reimbursed under this subsection may exceed per diem amounts established in official travel regulations, but the Commission may include in its regulations under this subsection a limitation on such amounts."],[0,"(d) Acceptance of relocation expenses from former employers by professional fellows program participants"],[0,"Notwithstanding any other provision of law, former employers of participants in the Commission's professional fellows programs may pay such participants their actual expenses for relocation to Washington, District of Columbia, to facilitate their participation in such programs, and program participants may accept such payments."],[0,"(e) Fee payments"],[0,"Notwithstanding any other provision of law, whenever any fee is required to be paid to the Commission pursuant to any provision of the securities laws or any other law, the Commission may provide by rule that such fee shall be paid in a manner other than in cash and the Commission may also specify the time that such fee shall be determined and paid relative to the filing of any statement or document with the Commission."],[0,"(f) Reimbursement of expenses for assisting foreign securities authorities"],[0,"Notwithstanding any other provision of law, the Commission may accept payment and reimbursement, in cash or in kind, from a foreign securities authority, or made on behalf of such authority, for necessary expenses incurred by the Commission, its members, and employees in carrying out any investigation pursuant to section 78u(a)(2) of this title or in providing any other assistance to a foreign securities authority. Any payment or reimbursement accepted shall be considered a reimbursement to the appropriated funds of the Commission."],[0,"(g) Office of the Investor Advocate"],[0,"(1) Office established"],[1,"There is established within the Commission the Office of the Investor Advocate (in this subsection referred to as the \"Office\")."],[0,"(2) Investor Advocate"],[0,"(A) In general"],[2,"The head of the Office shall be the Investor Advocate, who shall—"],[3,"(i) report directly to the Chairman; and"],[3,"(ii) be appointed by the Chairman, in consultation with the Commission, from among individuals having experience in advocating for the interests of investors in securities and investor protection issues, from the perspective of investors."],[0,"(B) Compensation"],[2,"The annual rate of pay for the Investor Advocate shall be equal to the highest rate of annual pay for other senior executives who report to the Chairman of the Commission."],[0,"(C) Limitation on service"],[2,"An individual who serves as the Investor Advocate may not be employed by the Commission—"],[3,"(i) during the 2-year period ending on the date of appointment as Investor Advocate; or"],[3,"(ii) during the 5-year period beginning on the date on which the person ceases to serve as the Investor Advocate."],[0,"(3) Staff of Office"],[1,"The Investor Advocate, after consultation with the Chairman of the Commission, may retain or employ independent counsel, research staff, and service staff, as the Investor Advocate deems necessary to carry out the functions, powers, and duties of the Office."],[0,"(4) Functions of the Investor Advocate"],[1,"The Investor Advocate shall—"],[2,"(A) assist retail investors in resolving significant problems such investors may have with the Commission or with self-regulatory organizations;"],[2,"(B) identify areas in which investors would benefit from changes in the regulations of the Commission or the rules of self-regulatory organizations;"],[2,"(C) identify problems that investors have with financial service providers and investment products;"],[2,"(D) analyze the potential impact on investors of—"],[3,"(i) proposed regulations of the Commission; and"],[3,"(ii) proposed rules of self-regulatory organizations registered under this chapter; and"],[2,"(E) to the extent practicable, propose to the Commission changes in the regulations or orders of the Commission and to Congress any legislative, administrative, or personnel changes that may be appropriate to mitigate problems identified under this paragraph and to promote the interests of investors."],[0,"(5) Access to documents"],[1,"The Commission shall ensure that the Investor Advocate has full access to the documents of the Commission and any self-regulatory organization, as necessary to carry out the functions of the Office."],[0,"(6) Annual reports"],[0,"(A) Report on objectives"],[0,"(i) In general"],[3,"Not later than June 30 of each year after 2010, the Investor Advocate shall submit to the Committee on Banking, Housing, and Urban Affairs of the Senate and the Committee on Financial Services of the House of Representatives a report on the objectives of the Investor Advocate for the following fiscal year."],[0,"(ii) Contents"],[3,"Each report required under clause (i) shall contain full and substantive analysis and explanation."],[0,"(B) Report on activities"],[0,"(i) In general"],[3,"Not later than December 31 of each year after 2010, the Investor Advocate shall submit to the Committee on Banking, Housing, and Urban Affairs of the Senate and the Committee on Financial Services of the House of Representatives a report on the activities of the Investor Advocate during the immediately preceding fiscal year."],[0,"(ii) Contents"],[3,"Each report required under clause (i) shall include—"],[4,"(I) appropriate statistical information and full and substantive analysis;"],[4,"(II) information on steps that the Investor Advocate has taken during the reporting period to improve investor services and the responsiveness of the Commission and self-regulatory organizations to investor concerns;"],[4,"(III) a summary of the most serious problems encountered by investors during the reporting period;"],[4,"(IV) an inventory of the items described in subclause (III) that includes—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78d?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§78d. Securities and Exchange Commission","tname":"Commerce and Trade","by":{"0":"2","1":"2"}},{"t":"usc","label":"15 U.S.C. § 78d-1","url":"https://www.law.cornell.edu/uscode/text/15/78d-1","subs":["(a)","(c)"],"stext":{"head":"§78d–1. Delegation of functions by Commission","paras":[[0,"(a) Authorization; functions delegable; eligible persons; application of other laws"],[0,"In addition to its existing authority, the Securities and Exchange Commission shall have the authority to delegate, by published order or rule, any of its functions to a division of the Commission, an individual Commissioner, an administrative law judge, or an employee or employee board, including functions with respect to hearing, determining, ordering, certifying, reporting, or otherwise acting as to any work, business, or matter. Nothing in this section shall be deemed to supersede the provisions of section 556(b) of title 5, or to authorize the delegation of the function of rulemaking as defined in subchapter II of chapter 5 of title 5, with reference to general rules as distinguished from rules of particular applicability, or of the making of any rule pursuant to section 78s(c) of this title."],[0,"(b) Right of review; procedure"],[0,"With respect to the delegation of any of its functions, as provided in subsection (a) of this section, the Commission shall retain a discretionary right to review the action of any such division of the Commission, individual Commissioner, administrative law judge, employee, or employee board, upon its own initiative or upon petition of a party to or intervenor in such action, within such time and in such manner as the Commission by rule shall prescribe. The vote of one member of the Commission shall be sufficient to bring any such action before the Commission for review. A person or party shall be entitled to review by the Commission if he or it is adversely affected by action at a delegated level which (1) denies any request for action pursuant to section 77h(a) or section 77h(c) of this title or the first sentence of section 78l(d) of this title; (2) suspends trading in a security pursuant to section 78l(k) of this title; or (3) is pursuant to any provision of this chapter in a case of adjudication, as defined in section 551 of title 5, not required by this chapter to be determined on the record after notice and opportunity for hearing (except to the extent there is involved a matter described in section 554(a)(1) through (6) of such title 5)."],[0,"(c) Finality of delegated action"],[0,"If the right to exercise such review is declined, or if no such review is sought within the time stated in the rules promulgated by the Commission, then the action of any such division of the Commission, individual Commissioner, administrative law judge, employee, or employee board, shall, for all purposes, including appeal or review thereof, be deemed the action of the Commission."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78d-1?type=usc&year=mostrecent&link-type=html"},"head":"§78d–1. Delegation of functions by Commission","tname":"Commerce and Trade","by":{"0":"2, 4, 6, 7, 23, 35","1":"2, 31, 2, 31","2":"5, 15"}},{"t":"usc","label":"15 U.S.C. § 78u","url":"https://www.law.cornell.edu/uscode/text/15/78u","stext":{"head":"§78u. Investigations and actions","paras":[[0,"(a) Authority and discretion of Commission to investigate violations"],[0,"(1) The Commission may, in its discretion, make such investigations as it deems necessary to determine whether any person has violated, is violating, or is about to violate any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated, or, as to any act or practice, or omission to act, while associated with a member, formerly associated with a member, the rules of a registered clearing agency in which such person is a participant, or, as to any act or practice, or omission to act, while a participant, was a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm, a person associated with such a firm, or, as to any act, practice, or omission to act, while associated with such firm, a person formerly associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, and may require or permit any person to file with it a statement in writing, under oath or otherwise as the Commission shall determine, as to all the facts and circumstances concerning the matter to be investigated. The Commission is authorized in its discretion, to publish information concerning any such violations, and to investigate any facts, conditions, practices, or matters which it may deem necessary or proper to aid in the enforcement of such provisions, in the prescribing of rules and regulations under this chapter, or in securing information to serve as a basis for recommending further legislation concerning the matters to which this chapter relates."],[0,"(2) On request from a foreign securities authority, the Commission may provide assistance in accordance with this paragraph if the requesting authority states that the requesting authority is conducting an investigation which it deems necessary to determine whether any person has violated, is violating, or is about to violate any laws or rules relating to securities matters that the requesting authority administers or enforces. The Commission may, in its discretion, conduct such investigation as the Commission deems necessary to collect information and evidence pertinent to the request for assistance. Such assistance may be provided without regard to whether the facts stated in the request would also constitute a violation of the laws of the United States. In deciding whether to provide such assistance, the Commission shall consider whether (A) the requesting authority has agreed to provide reciprocal assistance in securities matters to the Commission; and (B) compliance with the request would prejudice the public interest of the United States."],[0,"(b) Attendance of witnesses; production of records"],[0,"For the purpose of any such investigation, or any other proceeding under this chapter, any member of the Commission or any officer designated by it is empowered to administer oaths and affirmations, subpena witnesses, compel their attendance, take evidence, and require the production of any books, papers, correspondence, memoranda, or other records which the Commission deems relevant or material to the inquiry. Such attendance of witnesses and the production of any such records may be required from any place in the United States or any State at any designated place of hearing."],[0,"(c) Judicial enforcement of investigative power of Commission; refusal to obey subpena; criminal sanctions"],[0,"In case of contumacy by, or refusal to obey a subpena issued to, any person, the Commission may invoke the aid of any court of the United States within the jurisdiction of which such investigation or proceeding is carried on, or where such person resides or carries on business, in requiring the attendance and testimony of witnesses and the production of books, papers, correspondence, memoranda, and other records. And such court may issue an order requiring such person to appear before the Commission or member or officer designated by the Commission, there to produce records, if so ordered, or to give testimony touching the matter under investigation or in question; and any failure to obey such order of the court may be punished by such court as a contempt thereof. All process in any such case may be served in the judicial district whereof such person is an inhabitant or wherever he may be found. Any person who shall, without just cause, fail or refuse to attend and testify or to answer any lawful inquiry or to produce books, papers, correspondence, memoranda, and other records, if in his power so to do, in obedience to the subpena of the Commission, shall be guilty of a misdemeanor and, upon conviction, shall be subject to a fine of not more than $1,000 or to imprisonment for a term of not more than one year, or both."],[0,"(d) Injunction proceedings; authority of court to prohibit persons from serving as officers and directors; money penalties in civil actions; disgorgement"],[0,"(1) Whenever it shall appear to the Commission that any person is engaged or is about to engage in acts or practices constituting a violation of any provision of this chapter, the rules or regulations thereunder, the rules of a national securities exchange or registered securities association of which such person is a member or a person associated with a member, the rules of a registered clearing agency in which such person is a participant, the rules of the Public Company Accounting Oversight Board, of which such person is a registered public accounting firm or a person associated with such a firm, or the rules of the Municipal Securities Rulemaking Board, it may in its discretion bring an action in the proper district court of the United States, the United States District Court for the District of Columbia, or the United States courts of any territory or other place subject to the jurisdiction of the United States, to enjoin such acts or practices, and upon a proper showing a permanent or temporary injunction or restraining order shall be granted without bond. The Commission may transmit such evidence as may be available concerning such acts or practices as may constitute a violation of any provision of this chapter or the rules or regulations thereunder to the Attorney General, who may, in his discretion, institute the necessary criminal proceedings under this chapter."],[0,"(2) Authority of Court To Prohibit Persons From Serving as Officers and Directors.—In any proceeding under paragraph (1) of this subsection, the court may prohibit, conditionally or unconditionally, and permanently or for such period of time as it shall determine, any person who violated section 78j(b) of this title or the rules or regulations thereunder from acting as an officer or director of any issuer that has a class of securities registered pursuant to section 78l of this title or that is required to file reports pursuant to section 78o(d) of this title if the person's conduct demonstrates unfitness to serve as an officer or director of any such issuer."],[0,"(3) Civil money penalties and authority to seek disgorgement.—"],[1,"(A) Authority of commission.—Whenever it shall appear to the Commission that any person has violated any provision of this chapter, the rules or regulations thereunder, or a cease-and-desist order entered by the Commission pursuant to section 78u–3 of this title, other than by committing a violation subject to a penalty pursuant to section 78u–1 of this title, the Commission may bring an action in a United States district court to seek, and the court shall have jurisdiction to—"],[2,"(i) impose, upon a proper showing, a civil penalty to be paid by the person who committed such violation; and"],[2,"(ii) require disgorgement under paragraph (7) of any unjust enrichment by the person who received such unjust enrichment as a result of such violation."],[1,"(B) Amount of penalty.—"],[2,"(i) First tier.—The amount of a civil penalty imposed under subparagraph (A)(i) shall be determined by the court in light of the facts and circumstances. For each violation, the amount of the penalty shall not exceed the greater of (I) $5,000 for a natural person or $50,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation."],[2,"(ii) Second tier.—Notwithstanding clause (i), the amount of a civil penalty imposed under subparagraph (A)(i) for each such violation shall not exceed the greater of (I) $50,000 for a natural person or $250,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if the violation described in subparagraph (A) involved fraud, deceit, manipulation, or deliberate or reckless disregard of a regulatory requirement."],[2,"(iii) Third tier.—Notwithstanding clauses (i) and (ii), the amount of a civil penalty imposed under subparagraph (A)(i) for each violation described in that subparagraph shall not exceed the greater of (I) $100,000 for a natural person or $500,000 for any other person, or (II) the gross amount of pecuniary gain to such defendant as a result of the violation, if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/15/78u?type=usc&year=mostrecent&link-type=html"},"head":"§78u. Investigations and actions","tname":"Commerce and Trade","by":{"0":"2, 40","2":"16"}},{"t":"usc","label":"15 U.S.C. § 78u-2","url":"https://www.law.cornell.edu/uscode/text/15/78u-2","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 78v","url":"https://www.law.cornell.edu/uscode/text/15/78v","by":{"0":"2, 3, 35, 40","2":"20"}},{"t":"usc","label":"15 U.S.C. § 80a-40","url":"https://www.law.cornell.edu/uscode/text/15/80a-40","by":{"0":"3, 35","2":"20"}},{"t":"usc","label":"15 U.S.C. § 80b-9","url":"https://www.law.cornell.edu/uscode/text/15/80b-9","by":{"0":"2"}},{"t":"usc","label":"15 U.S.C. § 80b-12","url":"https://www.law.cornell.edu/uscode/text/15/80b-12","by":{"0":"3, 35","2":"20"}},{"t":"usc","label":"15 U.S.C. § 717","url":"https://www.law.cornell.edu/uscode/text/15/717","by":{"0":"35"}},{"t":"usc","label":"15 U.S.C. § 803","url":"https://www.law.cornell.edu/uscode/text/15/803","by":{"0":"56"}},{"t":"usc","label":"26 U.S.C. § 7456","url":"https://www.law.cornell.edu/uscode/text/26/7456","subs":["(c)"],"stext":{"head":"§7456. Administration of oaths and procurement of testimony","paras":[[0,"(a) In general"],[0,"For the efficient administration of the functions vested in the Tax Court or any division thereof, any judge or special trial judge of the Tax Court, the clerk of the court or his deputies, as such, or any other employee of the Tax Court designated in writing for the purpose by the chief judge, may administer oaths, and any judge or special trial judge of the Tax Court may examine witnesses and require, by subpoena ordered by the Tax Court or any division thereof and signed by the judge or special trial judge (or by the clerk of the Tax Court or by any other employee of the Tax Court when acting as deputy clerk)—"],[1,"(1) the attendance and testimony of witnesses, and the production of all necessary returns, books, papers, documents, correspondence, and other evidence, from any place in the United States at any designated place of hearing, or"],[1,"(2) the taking of a deposition before any designated individual competent to administer oaths under this title. In the case of a deposition the testimony shall be reduced to writing by the individual taking the deposition or under his direction and shall then be subscribed by the deponent."],[0,"(b) Production of records in the case of foreign corporations, foreign trusts or estates and nonresident alien individuals"],[0,"The Tax Court or any division thereof, upon motion and notice by the Secretary, and upon good cause shown therefor, shall order any foreign corporation, foreign trust or estate, or nonresident alien individual, who has filed a petition with the Tax Court, to produce, or, upon satisfactory proof to the Tax Court or any of its divisions, that the petitioner is unable to produce, to make available to the Secretary, and, in either case, to permit the inspection, copying, or photographing of, such books, records, documents, memoranda, correspondence and other papers, wherever situated, as the Tax Court or any division thereof, may deem relevant to the proceedings and which are in the possession, custody or control of the petitioner, or of any person directly or indirectly under his control or having control over him or subject to the same common control. If the petitioner fails or refuses to comply with any of the provisions of such order, after reasonable time for compliance has been afforded to him, the Tax Court or any division thereof, upon motion, shall make an order striking out pleadings or parts thereof, or dismissing the proceeding or any part thereof, or rendering a judgment by default against the petitioner. For the purpose of this subsection, the term \"foreign trust or estate\" includes an estate or trust, any fiduciary of which is a foreign corporation or nonresident alien individual; and the term \"control\" is not limited to legal control."],[0,"(c) Incidental powers"],[0,"The Tax Court and each division thereof shall have power to punish by fine or imprisonment, at its discretion, such contempt of its authority, and none other, as—"],[1,"(1) misbehavior of any person in its presence or so near thereto as to obstruct the administration of justice;"],[1,"(2) misbehavior of any of its officers in their official transactions; or"],[1,"(3) disobedience or resistance to its lawful writ, process, order, rule, decree, or command."],[0,"It shall have such assistance in the carrying out of its lawful writ, process, order, rule, decree, or command as is available to a court of the United States. The United States marshal for any district in which the Tax Court is sitting shall, when requested by the chief judge of the Tax Court, attend any session of the Tax Court in such district and may otherwise provide, when requested by the chief judge of the Tax Court, for the security of the Tax Court, including the personal protection of Tax Court judges, court officers, witnesses, and other threatened persons in the interests of justice, where criminal intimidation impedes on the functioning of the judicial process or any other official proceeding. The United States Marshals Service retains final authority regarding security requirements for the Tax Court."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/26/7456?type=usc&year=mostrecent&link-type=html"},"head":"§7456. Administration of oaths and procurement of testimony","tname":"Internal Revenue Code","by":{"0":"23","1":"21","2":"6"}},{"t":"usc","label":"28 U.S.C. § 636","url":"https://www.law.cornell.edu/uscode/text/28/636","by":{"0":"30"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"reg","label":"5 C.F.R. § 930.204","url":"https://www.ecfr.gov/current/title-5/section-930.204","by":{"0":"21"}},{"t":"reg","label":"17 C.F.R. § 200.14","url":"https://www.ecfr.gov/current/title-17/section-200.14","by":{"0":"21, 22, 23","2":"3, 15"}},{"t":"reg","label":"17 C.F.R. § 201.110","url":"https://www.ecfr.gov/current/title-17/section-201.110","by":{"0":"3, 48"}},{"t":"reg","label":"17 C.F.R. § 201.111","url":"https://www.ecfr.gov/current/title-17/section-201.111","by":{"0":"3, 4, 21, 22, 23","2":"3, 6, 15"}},{"t":"reg","label":"17 C.F.R. § 201.141","url":"https://www.ecfr.gov/current/title-17/section-201.141","by":{"0":"23"}},{"t":"reg","label":"17 C.F.R. § 201.155","url":"https://www.ecfr.gov/current/title-17/section-201.155","by":{"0":"4, 22, 32"}},{"t":"reg","label":"17 C.F.R. § 201.161","url":"https://www.ecfr.gov/current/title-17/section-201.161","by":{"0":"22"}},{"t":"reg","label":"17 C.F.R. § 201.180","url":"https://www.ecfr.gov/current/title-17/section-201.180","by":{"0":"4, 22, 23","2":"4, 6, 15"}},{"t":"reg","label":"17 C.F.R. § 201.200","url":"https://www.ecfr.gov/current/title-17/section-201.200","by":{"0":"21"}},{"t":"reg","label":"17 C.F.R. § 201.201","url":"https://www.ecfr.gov/current/title-17/section-201.201","by":{"0":"22"}},{"t":"reg","label":"17 C.F.R. § 201.221","url":"https://www.ecfr.gov/current/title-17/section-201.221","by":{"0":"22"}},{"t":"reg","label":"17 C.F.R. § 201.222","url":"https://www.ecfr.gov/current/title-17/section-201.222","by":{"0":"22"}},{"t":"reg","label":"17 C.F.R. § 201.230","url":"https://www.ecfr.gov/current/title-17/section-201.230","by":{"0":"4, 22","2":"3"}},{"t":"reg","label":"17 C.F.R. § 201.232","url":"https://www.ecfr.gov/current/title-17/section-201.232","by":{"0":"4, 22","2":"3"}},{"t":"reg","label":"17 C.F.R. § 201.233","url":"https://www.ecfr.gov/current/title-17/section-201.233","by":{"0":"4, 22","2":"3"}},{"t":"reg","label":"17 C.F.R. § 201.234","url":"https://www.ecfr.gov/current/title-17/section-201.234","by":{"0":"4, 22","2":"3"}},{"t":"reg","label":"17 C.F.R. § 201.250","url":"https://www.ecfr.gov/current/title-17/section-201.250","by":{"0":"4, 22"}},{"t":"reg","label":"17 C.F.R. § 201.320","url":"https://www.ecfr.gov/current/title-17/section-201.320","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. § 201.321","url":"https://www.ecfr.gov/current/title-17/section-201.321","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. § 201.322","url":"https://www.ecfr.gov/current/title-17/section-201.322","by":{"0":"4, 22"}},{"t":"reg","label":"17 C.F.R. § 201.323","url":"https://www.ecfr.gov/current/title-17/section-201.323","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. § 201.324","url":"https://www.ecfr.gov/current/title-17/section-201.324","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. § 201.325","url":"https://www.ecfr.gov/current/title-17/section-201.325","by":{"0":"4"}},{"t":"reg","label":"17 C.F.R. § 201.326","url":"https://www.ecfr.gov/current/title-17/section-201.326","by":{"0":"4, 23","2":"3"}},{"t":"reg","label":"17 C.F.R. § 201.360","url":"https://www.ecfr.gov/current/title-17/section-201.360","by":{"0":"4, 23, 32, 33","2":"5, 14"}},{"t":"reg","label":"17 C.F.R. § 201.410","url":"https://www.ecfr.gov/current/title-17/section-201.410","by":{"0":"33"}},{"t":"reg","label":"17 C.F.R. § 201.411","url":"https://www.ecfr.gov/current/title-17/section-201.411","by":{"0":"33"}},{"t":"case","label":"Bowsher v. Synar","cite":"478 U.S. 714","y":1986,"id":"1985/85-1377","sc":1,"sum":"The Court found that the duties which the Congress delegated to the Comptroller General did violate the doctrine of separation of powers and were unconstitutional. A two step process led Chief Justice Burger to arrive at this conclusion.","sumSrc":"Oyez","by":{"1":"41","2":"16"}},{"t":"case","label":"Federal Maritime Comm’n v. South Carolina State Ports Auth.","cite":"535 U.S. 743","y":2002,"id":"2001/01-46","sc":1,"sum":"The Court held that state sovereign immunity bars the FMC from adjudicating a private party's complaint against a nonconsenting State. Historically, the Court noted, states were not subject to private suits in administrative adjudications when the Constitution was adopted, and states were thus presumptively immune from such actions.","sumSrc":"Oyez","by":{"1":"30, 31"}},{"t":"case","label":"Mahoney v. Donovan","cite":"721 F.3d 633","y":2013,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/721/633/","by":{"1":"55"}},{"t":"case","label":"Morrison v. Olson","cite":"487 U.S. 654","y":1988,"id":"1987/87-1279","sc":1,"sum":"The near-unanimous Court held that the means of selecting the independent counsel did not violate the Appointments Clause; the powers allocated to the special court did not violate Article III; and the Act was not offensive to the separation of powers doctrine since it did not impermissibly interfere with the functions of the Executive Branch.","sumSrc":"Oyez","by":{"1":"43, 50"}},{"t":"case","label":"Nephew v. Willis","cite":"298 N.W. 376","y":1941,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W./298/376/","by":{"1":"49"}},{"t":"case","label":"Printz v. United States","cite":"521 U.S. 898","y":1997,"id":"1996/95-1478","sc":1,"sum":"The Court held that Congress could not require state agencies to perform federal duties under the Necessary and Proper Clause.","sumSrc":"Oyez","by":{"1":"55"}},{"t":"case","label":"Public Citizen v. Department of Justice","cite":"491 U.S. 440","y":1989,"id":"1988/88-429","sc":1,"sum":"To aid the President in fulfilling his constitutional duty to appoint federal judges, the Department of Justice regularly seeks advice from the Standing Committee on Federal Judiciary of the American Bar Association (ABA) regarding potential nominees for judgeships. The ABA Committee's investigations, reports, and votes on potential nominees are kept confidential, although its rating of a particular candidate is …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"50"}},{"t":"case","label":"Shapiro v. Social Sec. Admin.","cite":"800 F.3d 1332","y":2015,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/800/1332/","by":{"1":"47"}},{"t":"case","label":"Social Sec. Admin. v. Anyel","cite":"58 M.S.P.R. 261","y":1993,"court":"MSPB","url":"https://www.courtlistener.com/c/M.S.P.R./58/261/","by":{"1":"46"}},{"t":"case","label":"Social Sec. Admin. v. Boini","cite":"123 M.S.P.R. 302","y":2016,"court":"MSPB","url":"https://www.courtlistener.com/c/M.S.P.R./123/302/","by":{"1":"54"}},{"t":"case","label":"Social Sec. Admin. v. Brennan","cite":"27 M.S.P.R. 242","y":1985,"court":"MSPB","url":"https://www.courtlistener.com/c/M.S.P.R./27/242/","by":{"1":"47"}},{"t":"case","label":"Social Sec. Admin. v. Glover","cite":"23 M.S.P.R. 57","y":1984,"court":"MSPB","url":"https://www.courtlistener.com/c/M.S.P.R./23/57/","by":{"1":"47, 52"}},{"t":"case","label":"Social Sec. Admin. v. Goodman","cite":"19 M.S.P.R. 321","y":1984,"court":"MSPB","url":"https://www.courtlistener.com/c/M.S.P.R./19/321/","by":{"1":"47"}},{"t":"case","label":"Social Sec. Admin. v. Long","cite":"113 M.S.P.R. 190","y":2010,"court":"MSPB","url":"https://www.courtlistener.com/c/M.S.P.R./113/190/","by":{"1":"54"}},{"t":"case","label":"Universal Camera Corp. v. NLRB","cite":"340 U.S. 474","y":1951,"id":"scdb/1950-038","sc":1,"sum":"The National Labor Relations Board ordered petitioner to reinstate with back pay an employee found to have been discharged because he gave certain testimony in another proceeding under the National Labor Relations Act. The evidence as to the reason for his discharge was conflicting; and the Board overruled its examiner's findings of fact and his recommendation that the proceedings be dismissed. In decreeing …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 28","2":"14"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"1":"25, 49"}},{"t":"usc","label":"5 U.S.C. § 551","url":"https://www.law.cornell.edu/uscode/text/5/551","by":{"1":"25"}},{"t":"usc","label":"5 U.S.C. § 553","url":"https://www.law.cornell.edu/uscode/text/5/553","subs":["(c)"],"by":{"1":"3"}},{"t":"usc","label":"5 U.S.C. § 554","url":"https://www.law.cornell.edu/uscode/text/5/554","subs":["(a)"],"stext":{"head":"§554. Adjudications","paras":[[0,"(a) This section applies, according to the provisions thereof, in every case of adjudication required by statute to be determined on the record after opportunity for an agency hearing, except to the extent that there is involved—"],[1,"(1) a matter subject to a subsequent trial of the law and the facts de novo in a court;"],[1,"(2) the selection or tenure of an employee, except a 1 administrative law judge appointed under section 3105 of this title;"],[1,"(3) proceedings in which decisions rest solely on inspections, tests, or elections;"],[1,"(4) the conduct of military or foreign affairs functions;"],[1,"(5) cases in which an agency is acting as an agent for a court; or"],[1,"(6) the certification of worker representatives."],[0,"(b) Persons entitled to notice of an agency hearing shall be timely informed of—"],[1,"(1) the time, place, and nature of the hearing;"],[1,"(2) the legal authority and jurisdiction under which the hearing is to be held; and"],[1,"(3) the matters of fact and law asserted."],[0,"When private persons are the moving parties, other parties to the proceeding shall give prompt notice of issues controverted in fact or law; and in other instances agencies may by rule require responsive pleading. In fixing the time and place for hearings, due regard shall be had for the convenience and necessity of the parties or their representatives."],[0,"(c) The agency shall give all interested parties opportunity for—"],[1,"(1) the submission and consideration of facts, arguments, offers of settlement, or proposals of adjustment when time, the nature of the proceeding, and the public interest permit; and"],[1,"(2) to the extent that the parties are unable so to determine a controversy by consent, hearing and decision on notice and in accordance with sections 556 and 557 of this title."],[0,"(d) The employee who presides at the reception of evidence pursuant to section 556 of this title shall make the recommended decision or initial decision required by section 557 of this title, unless he becomes unavailable to the agency. Except to the extent required for the disposition of ex parte matters as authorized by law, such an employee may not—"],[1,"(1) consult a person or party on a fact in issue, unless on notice and opportunity for all parties to participate; or"],[1,"(2) be responsible to or subject to the supervision or direction of an employee or agent engaged in the performance of investigative or prosecuting functions for an agency."],[0,"An employee or agent engaged in the performance of investigative or prosecuting functions for an agency in a case may not, in that or a factually related case, participate or advise in the decision, recommended decision, or agency review pursuant to section 557 of this title, except as witness or counsel in public proceedings. This subsection does not apply—"],[1,"(A) in determining applications for initial licenses;"],[1,"(B) to proceedings involving the validity or application of rates, facilities, or practices of public utilities or carriers; or"],[1,"(C) to the agency or a member or members of the body comprising the agency."],[0,"(e) The agency, with like effect as in the case of other orders, and in its sound discretion, may issue a declaratory order to terminate a controversy or remove uncertainty."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/5/554?type=usc&year=mostrecent&link-type=html"},"ar":1,"head":"§554. Adjudications","tname":"Government Organization and Employees","by":{"1":"3"}},{"t":"usc","label":"5 U.S.C. § 1201","url":"https://www.law.cornell.edu/uscode/text/5/1201","by":{"1":"5"}},{"t":"usc","label":"5 U.S.C. § 3344","url":"https://www.law.cornell.edu/uscode/text/5/3344","by":{"1":"5"}},{"t":"usc","label":"5 U.S.C. § 7513","url":"https://www.law.cornell.edu/uscode/text/5/7513","subs":["(b)"],"by":{"1":"54"}},{"t":"usc","label":"5 U.S.C. § 7701","url":"https://www.law.cornell.edu/uscode/text/5/7701","subs":["(b)(2)"],"by":{"1":"54"}},{"t":"usc","label":"5 U.S.C. § 7703","url":"https://www.law.cornell.edu/uscode/text/5/7703","subs":["(d)(1)"],"by":{"1":"6, 6"}},{"t":"law","label":"Dodd-Frank Wall Street Reform and Consumer Protection Act, Pub. L. No. 111-203","url":"https://www.govinfo.gov/link/plaw/111/public/203","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 80b-1","url":"https://www.law.cornell.edu/uscode/text/15/80b-1","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 80b-3","url":"https://www.law.cornell.edu/uscode/text/15/80b-3","subs":["(e)","(k)"],"by":{"1":"31, 2, 2, 31, 2"}},{"t":"usc","label":"15 U.S.C. § 80b-13","url":"https://www.law.cornell.edu/uscode/text/15/80b-13","subs":["(a)"],"by":{"1":"5"}},{"t":"usc","label":"15 U.S.C. § 80a-1","url":"https://www.law.cornell.edu/uscode/text/15/80a-1","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 80a-9","url":"https://www.law.cornell.edu/uscode/text/15/80a-9","subs":["(b)"],"by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 80a-41","url":"https://www.law.cornell.edu/uscode/text/15/80a-41","subs":["(a)"],"by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 80a-42","url":"https://www.law.cornell.edu/uscode/text/15/80a-42","subs":["(a)"],"by":{"1":"5"}},{"t":"law","label":"Pub. L. No. 91-547","url":"https://www.govinfo.gov/link/statute/84/1431","by":{"1":"31"}},{"t":"usc","label":"15 U.S.C. § 7201","url":"https://www.law.cornell.edu/uscode/text/15/7201","by":{"1":"44"}},{"t":"usc","label":"15 U.S.C. § 7217","url":"https://www.law.cornell.edu/uscode/text/15/7217","subs":["(d)(3)"],"by":{"1":"44"}},{"t":"usc","label":"15 U.S.C. § 77a","url":"https://www.law.cornell.edu/uscode/text/15/77a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 77h","url":"https://www.law.cornell.edu/uscode/text/15/77h","by":{"1":"31"}},{"t":"usc","label":"15 U.S.C. § 77h-1","url":"https://www.law.cornell.edu/uscode/text/15/77h-1","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 77i","url":"https://www.law.cornell.edu/uscode/text/15/77i","subs":["(a)"],"by":{"1":"5"}},{"t":"usc","label":"15 U.S.C. § 77t","url":"https://www.law.cornell.edu/uscode/text/15/77t","subs":["(d)"],"by":{"1":"32"}},{"t":"law","label":"Pub. L. No. 88-467","url":"https://www.govinfo.gov/link/statute/78/570","by":{"1":"31"}},{"t":"law","label":"Pub. L. No. 101-429","url":"https://www.govinfo.gov/link/statute/104/932","by":{"1":"32"}},{"t":"usc","label":"15 U.S.C. § 78a","url":"https://www.law.cornell.edu/uscode/text/15/78a","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78o","url":"https://www.law.cornell.edu/uscode/text/15/78o","by":{"1":"2, 31"}},{"t":"usc","label":"15 U.S.C. § 78u-3","url":"https://www.law.cornell.edu/uscode/text/15/78u-3","by":{"1":"2"}},{"t":"usc","label":"15 U.S.C. § 78y","url":"https://www.law.cornell.edu/uscode/text/15/78y","subs":["(a)(1)","(a)(3)"],"by":{"1":"5, 3"}},{"t":"usc","label":"26 U.S.C. § 7443A","url":"https://www.law.cornell.edu/uscode/text/26/7443A","subs":["(b)(1988)","(c)(1988)"],"by":{"1":"18, 18"}},{"t":"usc","label":"42 U.S.C. § 2000e-16","url":"https://www.law.cornell.edu/uscode/text/42/2000e-16","subs":["(a)"],"by":{"1":"50"}},{"t":"case","label":"Halliburton Co. v. Erica P. John Fund, Inc.","cite":"134 S. Ct. 2398","y":2014,"id":"2013/13-317","sc":1,"sum":"The Court held that there is no undue burden in allowing defendants in securities fraud cases from presenting evidence regarding the alleged impact of the misinformation on stock prices.","sumSrc":"Oyez","by":{"2":"1"}},{"t":"case","label":"Laccetti v. SEC, — F.3d —","cite":"2018 WL 1439616","y":2018,"court":"D.C. Cir. Mar. 23","by":{"2":"23"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"2":"2"}},{"t":"case","label":"Steele v. United States","cite":"267 U.S. 505","y":1925,"id":"scdb/1924-114","sc":1,"ar":1,"sum":"1. A judgment upholding a search warrant on a petition to vacate it is res judicata as to the -competency of the person to whom the warrant was directed and as to probable cause for its issuance; so that the petitioner cannot subsequently raise the question in a criminal proceeding' against him by objecting to evidence of seizure under the warrant.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"20"}},{"t":"case","label":"United States v. Maurice","cite":"26 F. Cas. 1211","y":1823,"court":"C.C.D. Va.","url":"https://www.courtlistener.com/c/F.%20Cas./26/1211/","by":{"2":"10"}},{"t":"usc","label":"5 U.S.C. § 2105","url":"https://www.law.cornell.edu/uscode/text/5/2105","by":{"2":"20"}}]};